{
  "packs": [
    "claudinite-lifecycle",
    "claudinite-tasks",
    "basics",
    {
      "id": "claudinite-growth",
      "config": {
        "pack_paths": [
          ".claudinite/local/packs",
          "packs"
        ]
      }
    },
    "tidy-repo",
    {
      "id": "local/claudinite",
      "config": {
        "canaryRepo": "missingbulb/ClaudiniteCanary"
      }
    },
    "local/canon-curation",
    {
      "id": "barriers",
      "answers": {
        "goals": "Keep extending.md's engine/content boundary structural: core (checks/, mount/, engine/, .github/, the top-level docs, and the shared engine modules under packs/ and skills/) must never name a specific pack or skill — packs and skills are discovered content, and a core file citing one couples the engine to its content. One rule per namespace (packs/*, skills/*); reviewed inherent couplings live in each rule's except. migrations/ is deliberately NOT core here: a migration record is a dated one-off that exists to move the fleet off a specific pack's old shape, so naming that pack is its purpose, not a coupling — and records accumulate as dated folders, one per change, which no path-keyed exception list should have to chase."
      },
      "config": {
        "rules": [
          {
            "from": [
              "engine",
              ".github",
              "bootstrap.md",
              "consumer-safe-changes.md",
              "extending.md"
            ],
            "to": "packs/*",
            "matchNames": true,
            "matchUniqueFilenames": false,
            "reason": "core is the engine that runs pack content — it must not name the specific packs it runs (extending.md)",
            "except": [
              {
                "path": ".github/workflows/README.md",
                "to": [
                  "packs/chrome-extension"
                ],
                "reason": "decouple(release-infra): the core .github/ README documents the chrome-extension release plumbing being vendored out of core (#276)"
              },
              {
                "path": ".github/workflows/chrome-extension-daily-release.yml",
                "to": [
                  "packs/chrome-extension"
                ],
                "reason": "decouple(release-infra): chrome-extension reusable release infra hosted in the core .github/ tree; being vendored out (#276)"
              },
              {
                "path": ".github/workflows/chrome-extension-publish-store.yml",
                "to": [
                  "packs/chrome-extension"
                ],
                "reason": "decouple(release-infra): chrome-extension reusable release infra hosted in the core .github/ tree; being vendored out (#276)"
              },
              {
                "path": ".github/workflows/chrome-extension-release.yml",
                "to": [
                  "packs/chrome-extension"
                ],
                "reason": "decouple(release-infra): chrome-extension reusable release infra hosted in the core .github/ tree; being vendored out (#276)"
              },
              {
                "path": "extending.md",
                "to": [
                  "packs/claudinite-lifecycle"
                ],
                "reason": "inherent(#385): the engine map documents where the adoption-interview machinery lives now that it is bundled in the adoption skill (moved with that skill into the claudinite-lifecycle pack, #835)"
              },
              {
          "path": ".github/workflows/claudinite-scheduler.yml",
          "to": [
            "packs/claudinite-tasks"
          ],
          "reason": "inherent(#1317): a member's scheduler workflow is the one file that cannot converge, so its `run:` line names the mount path of the pack that owns the run — the pack boundary is what the workflow points across"
        },
        {
          "path": ".github/workflows/claudinite-executor.yml",
          "to": [
            "packs/claudinite-tasks"
          ],
          "reason": "inherent(#1317): a member's executor workflow is the one file that cannot converge, so its `run:` line names the mount path of the pack that owns the executor"
        },
        "engine/migrations",
              {
                "path": "engine/pack_loader/renamed-packs.mjs",
                "to": [
                  "packs/claudinite-lifecycle",
                  "packs/claudinite-growth",
                  "packs/chrome-extension",
                  "packs/git-github",
                  "packs/claudinite-canary-repo",
                  "packs/claudinite-fleet-sheepdog"
                ],
                "reason": "inherent(#1022): a map from a pack's old id to its current one IS a list of pack names — there is nothing else for it to be made of, and the loader must hold it so a member declaring either spelling keeps its packs"
              },
              {
                "path": "engine/RELEASES.md",
                "to": [
                  "packs/claudinite-lifecycle",
                  "packs/claudinite-growth"
                ],
                "reason": "inherent(#1022): the release log says what each engine version shipped, and version 5 shipped a pack rename — a row that could not name the packs would not be a record of it"
              }
            ]
          },
          {
            "siblings": "packs",
            "to": "docs",
            "reason": "docs/ is outside the vendor set, so a pack file's reference to it resolves to nothing in every consumer (#424) — cite the doc from the issue or PR instead; a pack's updates/ is carved out because no vendor set carries that either, so the premise cannot arise there (#1317)",
            "except": [
              "packs/claudinite-lifecycle/updates"
            ]
          }
        ]
      }
    },
    {
      "id": "claude-code-web-users-support",
      "config": {
        "repo": "missingbulb/Shepherd"
      },
      "answers": {
        "store": "missingbulb/Shepherd — the fleet's own repo, which holds one <email>.md per person under preferences/"
      }
    }
  ],
  "accept": [
    {
      "rule": "task-code-work-env",
      "path": "packs/claudinite-lifecycle/tasks/update/worker.mjs",
      "reason": "the update worker has a SECOND, deliberate caller: .github/workflows/canary-rehearsal.yml drives it directly to qualify a release ref, and CLAUDINITE_CANON_REF is that harness's own parameter, set there and read nowhere else. The rule's concern is a parameter channel that has silently stopped being delivered; this one is delivered by the workflow beside it, in the same repo, and its absence under code-work is the normal case the worker already handles (rehearsalRef null = a real cycle)"
    },
    {
      "rule": "reference-integrity",
      "path": "docs/task-code-work/",
      "reason": "the task-code-work DESIGN is the dated record of migration #405 \u2014 it names the slot scheduler's entry point as the staging it was changing, and #974 has since deleted that module. The reference is dangling because the record is true of the moment it describes; repointing it at the queue's executor would make the document describe a design that never happened. Same standing as the per-project-scheduling entry below"
    },
    {
      "rule": "reference-integrity",
      "path": "packs/claudinite-tasks/test/legacy-protocol.mjs",
      "reason": "the file holds the LEGACY WIRE LITERALS, which are data rather than pointers: a work item minted before the task surface moved (#1317) still carries `engine/scheduler/` in its machine block, and `BUILT_IN_PATH_RE` accepts that root permanently because it is a validator — dropping it rejects that half of the ad-hoc request lane outright. The path must not resolve to a file; a decoder must keep understanding it. Collected here so this waiver is one entry rather than five across the tests that exercise the decode"
    },
    {
      "rule": "reference-integrity",
      "path": "docs/per-project-scheduling/",
      "reason": "the per-project-scheduling DESIGN/MIGRATION pair is the historical record of migration #394 — it names the central routine and planner files this migration deleted precisely because deleting them is what it records; rewriting those names would falsify the record, so its inbound-reference dangling is deliberate and permanent"
    },
    {
      "rule": "barrier",
      "path": ".github/workflows/canary-rehearsal.yml",
      "reason": "the live canary gate names packs/claudinite-lifecycle/tasks/update because the worker is ITSELF vendored content, so a release that changes the worker cannot be rehearsed by the canary's vendored copy — that copy predates the release by definition, and a rehearsal driving it would ignore CLAUDINITE_CANON_REF entirely and run a real cycle against main, opening a PR on the canary instead of qualifying the ref. The crossing buys the one property the gate exists for: the code under test is the code every member runs the moment the release reaches them. The workflow names no pack CONTENT — only the entry point of the task that performs the converge"
    }
  ],
  "taskScheduler": {
    "agenticTaskInvocationEndpoints": {
      "default": {
        "url": "[REDACTED:env:ANTHROPIC_BASE_URL]/v1/claude_code/routines/trig_01N7pUAHt3fs391BTqfN2bwM/fire",
        "tokenSecret": "CCR_ROUTINE_TOKEN"
      },
      "fleet": {
        "url": "[REDACTED:env:ANTHROPIC_BASE_URL]/v1/claude_code/routines/trig_0135i4BKGwoLbRGvKRiqqE4r/fire",
        "tokenSecret": "CCR_FLEET_ROUTINE_TOKEN"
      }
    },
    "dailyHour": 5,
    "weeklyDay": "Sun",
    "monthlyDay": 1
  }
}

// claudinite-growth task: usage-fold — the per-repo usage aggregate
// (skill-usage-metrics DESIGN §5). `agent_model: 'none'` with
// `code_work: 'node worker.mjs'`: the whole pass is deterministic code the
// executor runs as code-work — no agent phase, seconds of runtime.
//
// WHY: a skill is MOUNTED per repo, but mounting only puts a name and a one-line
// description into the session prompt — actually LOADING it is model discretion, and
// nothing recorded whether it ever happened. The only evidence is the session
// transcript, which is ephemeral and dies at retention on the logs branch. So the
// promotion ladder's skill-vs-prose call had no empirical feedback: a skill whose
// trigger never fires looked exactly like one that fires daily. This task counts
// loads — and the DENOMINATORS that make a count mean something — out of the logs
// this repo already captures, into a small tracked aggregate.
//
// It also counts what the MACHINERY did: how often the scheduler and the executor
// ran, how many of those hours a session actually opened, what each closed work item
// came to, and what landed in git. That half exists in a repo whose sessions are all
// unattended and captured nothing at all.
//
// WHY DAILY. The file is the whole past-data plane the dashboard renders from
// (claudinite-dashboard) — every panel that reaches further back than one page of live reads
// comes from here. It folded hourly until the scheduler's cron went to two ticks a day
// (tasks-dispatch DESIGN §17): a frequency finer than the cron cannot be honoured, since the
// anchor is only ever seen when a tick comes. Nothing about the DATA changes — hour rows are
// still recomputed from source across a three-day window, so only the newest rows' freshness
// moves, and the dashboard already tops up the freshest hours from the live run listing it
// fetches anyway. The precondition is what keeps a quiet repo quiet.
//
// Self-contained (imports nothing): the whole contract is this default export.

// The signal window a task is judged over: its own period plus the scheduler's hour of slack. A
// log stamped inside it is a session that ran since the last fold. This MUST track the declared
// frequency — sized to an hour while the task anchors daily, the "a session captured" arm never
// fires (a log is ~23h old by the next anchor) and a repo whose only movement is commit-less
// sessions silently stops folding altogether.
const WINDOW_DAYS = 25 / 24;

export default {
  id: 'usage-fold',
  frequency: 'daily',                    // see "WHY DAILY" in the header
  precondition_signals: ['commits', 'conversationLogs'],
  agent_model: 'none',                   // pure code — no agent (task-code-work DESIGN §4)
  expected_outcome: 'pr',
  // The regenerated aggregate is the whole delivery — scoped to the tree it
  // lands in, so a GENERATED file elsewhere in the repo is some other task's.
  // Its merge=ours line is seeded at adoption.
  automerge: ['under:.claudinite/local && generated-file-changes'],
  code_work: 'node worker.mjs',
  // One tree read plus one blob read per capture file in the ~10-day window, all
  // local git, then four REST reads and one PR. A busy repo captures a few files a
  // day, so this is seconds; 600s is ~100x that, generous enough that a huge backlog
  // on a first fold still completes while a hung run is killed well inside the hourly
  // cadence.
  code_work_timeout: 600,

  // Gated on the repo having MOVED this hour, which is the whole difference between an
  // hourly fold and an hourly PR. Two movements are visible to a collector and both
  // change the numbers: a commit on the default branch (the git series, and whatever
  // landed with it), and a conversation log stamped inside the window (a session ran).
  //
  // Deliberately NOT gated on the scheduler having run: it runs every hour by
  // definition, so that gate would be no gate at all. Its runs are not lost by
  // declining — they sit past the watermark and the next fold that does run reads
  // them, and the dashboard tops up the freshest hours from the live run listing it
  // already fetches.
  precondition(signals) {
    const commits = signals.commits ?? {};
    const logs = signals.conversationLogs ?? {};
    const moved = [];
    if (commits.count > 0) moved.push(`${commits.count} commit(s) on the default branch`);
    // `newestLogAgeDays` is null when the branch does not exist or carries no readable
    // stamp — unknown, which is not movement.
    if (logs.newestLogAgeDays !== null && logs.newestLogAgeDays !== undefined && logs.newestLogAgeDays <= WINDOW_DAYS) {
      moved.push('a session captured');
    }
    if (!moved.length) {
      return {
        run: false,
        reason: 'nothing moved this period — no commit on the default branch and no new conversation log; '
          + 'the run and queue reads stay past their watermarks for the next fold that has something to do',
      };
    }
    return { run: true, reason: `fold ${moved.join(' and ')} into the usage aggregate` };
  },
};

import { finding } from '../../../engine/checks/helpers/findings.mjs';
import {
  AUTOMERGE_TRAILER, AUTOMERGE_TRAILER_RE, policyVerdict, declaredMergeRules,
} from '../merge-policy.mjs';

// The armed-auto-merge gate: when a branch says it intends to land itself under
// a granular policy, the diff must actually sit inside that policy — re-checked
// here, at the Stop hook and on every PR, so a run that mis-measured (or lied
// about) its own diff goes red before GitHub's queued auto-merge can fire.
//
// SELF-GATING BY THE TRAILER, the shape improve-comments-scope keys on its
// pinned commit subject: a landing run stamps `Claudinite-Automerge-Policy:
// <expr>` into its final commit message (deliver-pr.md owns when), so this rule
// runs everywhere the pack is active and costs ~nothing on a branch that armed
// nothing. No trailer, no findings — a wide PR left open for review must stay
// green, since red CI would get it closed as failed rather than read. The LAST
// trailer on the branch wins: a run that re-measured after amending its scope
// states its final intent last.
//
// The policy is re-evaluated from the trailer, not re-read from the task
// declaration, because the branch may BE the thing changing declarations; what
// keeps the trailer honest is the policy engine's own self-widening guard — no
// granular policy covers a change to the policy sources — plus the landing lane
// only merging on the same verdict this rule computes.
const rule = {
  id: 'automerge-policy-scope',
  severity: 'blocking',
  scope: 'work',
  doc: 'packs/claudinite-tasks/README.md',
  description: 'A branch that stamps the Claudinite-Automerge-Policy trailer — its run intends to land its own PR — carries only a diff that policy actually covers',
  why: 'the trailer is a claim that this diff may merge with nobody looking; a diff outside the declared classes is exactly the unreviewed change the policy exists to stop, and only a check can hold the claim to the measurement',

  run(work) {
    if (work.onDefaultBranch()) return [];
    // work.commits is newest-first (git log order), so the newest commit's
    // trailer — the branch's final stated intent — is the first match.
    const armed = work.commits.map((m) => AUTOMERGE_TRAILER_RE.exec(m)?.[1]).find(Boolean);
    if (armed === undefined) return [];

    const deleted = new Set(work.deleted);
    const entries = [...new Set([...work.changedFiles, ...work.deleted])].sort().map((file) => ({
      file,
      before: work.readBase(file),
      after: deleted.has(file) ? null : work.read(file),
    }));
    const { rules, errors } = declaredMergeRules(work.packs, work.config);
    const verdict = policyVerdict({ policy: armed, entries, declaredRules: rules, ruleErrors: errors });
    if (verdict.mergeable) return [];

    return verdict.problems.map((p) => finding(rule, {
      file: p.file ?? '(branch)',
      what: `this branch armed auto-merge (${AUTOMERGE_TRAILER}: ${armed}) but ${p.what}`,
      fix: p.file
        ? `revert or split out ${p.file}, or drop the trailer from the branch's last commit and leave the PR for review — never widen the policy to fit the diff`
        : 'make the diff satisfy the armed policy, or drop the trailer and leave the PR for review',
    }));
  },
};

export default rule;

// The auto-merge policy engine, published for other packs: the verdict a
// `automerge` declaration compiles to, and the merge-rules.json compiler, so
// a pack's own tests can assert its policies and declared rules against the same
// evaluator the landing lane and the automerge-policy-scope gate apply.
export * from '../merge-policy.mjs';
